import sys
from datetime import datetime


def minutes(text):
    return int(text.split(":")[0]) * 60 + int(text.split(":")[1])


def is_peak_hour(start_time):
    h = int(start_time.split(":")[0])
    m = int(start_time.split(":")[1])
    return 8 <= h <= 19 and m >= 0


def compute_fee(duration_minutes):
    if duration_minutes <= 30:
        return 0.0
    blocks = (duration_minutes + 59) // 60
    fee = blocks * 2.50
    if fee > 18.00:
        fee = 18.00
    return fee


def process_stay(line):
    parts = line.split()
    if len(parts) != 5:
        print(f"{parts[0]} invalid")
        return

    plate = parts[0]
    entry_str = parts[1] + " " + parts[2]
    exit_str = parts[3] + " " + parts[4]

    try:
        entry = datetime.strptime(entry_str, "%Y-%m-%d %H:%M")
        exit_time = datetime.strptime(exit_str, "%Y-%m-%d %H:%M")
    except ValueError:
        print(f"{plate} invalid")
        return

    if exit_time <= entry:
        print(f"{plate} invalid")
        return

    duration = (exit_time - entry).total_seconds() / 60
    if duration < 0:
        print(f"{plate} invalid")
        return

    fee = compute_fee(duration)

    print(f"{plate} {int(duration):02d}:{int((duration % 1)*60):02d} {fee:.2f}")

    totals[plate] = totals.get(plate, 0.0) + fee


def main():
    totals = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        process_stay(line)

    print("---")

    valid_plates = {plate: total for plate, total in totals.items() if total > 0}
    sorted_plates = sorted(
        valid_plates.items(),
        key=lambda x: (-x[1], x[0]),
    )

    for plate, total in sorted_plates:
        print(f"{plate} {len([p for p, t in valid_plates.items() if p == plate])} {total:.2f}")


if __name__ == "__main__":
    totals = {}
    main()
